CREATE TABLE sessions (topic_id TEXT(8), group_id TEXT(8), season TEXT(6) CHECK (season IN ('Fall', 'Spring')), yr REAL(4, 0), PRIMARY KEY (topic_id, group_id, season, yr));

CREATE TABLE enrollments (member_id TEXT(5), topic_id TEXT(8), group_id TEXT(8), season TEXT(6), yr REAL(4, 0), PRIMARY KEY (member_id, topic_id, group_id, season, yr), FOREIGN KEY (topic_id, group_id, season, yr) REFERENCES sessions (topic_id, group_id, season, yr));

CREATE TABLE instructors_map (leader_id TEXT(5), topic_id TEXT(8), group_id TEXT(8), season TEXT(6), yr REAL(4, 0), PRIMARY KEY (leader_id, topic_id, group_id, season, yr), FOREIGN KEY (topic_id, group_id, season, yr) REFERENCES sessions (topic_id, group_id, season, yr));
